DROP FUNCTION IF EXISTS verificar_caso13(text);
DROP TABLE IF EXISTS bomba_evento, bomba_escala, bomba_prescricao, bomba_paciente, bomba_equipe CASCADE;

-- Equipe da UTI Adulto que usa as bombas (cada pessoa tem um crachá)
CREATE TABLE bomba_equipe (
  cracha  text PRIMARY KEY,  -- código do crachá, ex.: C-1875
  nome    text NOT NULL,
  cargo   text,
  turno   text
);

-- Pacientes internados na UTI Adulto, cada um com a sua bomba de infusão
CREATE TABLE bomba_paciente (
  id       integer PRIMARY KEY,
  nome     text NOT NULL,
  leito    text,
  peso_kg  numeric(5,1),
  bomba    text           -- código da bomba ligada ao paciente, ex.: BMB-03
);

-- Prescrição médica: a dose MÁXIMA autorizada de cada medicamento
CREATE TABLE bomba_prescricao (
  id           integer PRIMARY KEY,
  paciente_id  integer REFERENCES bomba_paciente(id),
  farmaco      text,          -- 'noradrenalina', 'heparina', 'insulina', 'fentanil', 'midazolam'
  modo         text,          -- 'continua' (gota a gota, por hora) ou 'bolus' (dose única de uma vez)
  dose         numeric,       -- dose máxima prescrita
  unidade      text,
  medico       text,
  data         date
);

-- Ponto eletrônico da UTI: quando cada pessoa entrou e saiu do plantão
CREATE TABLE bomba_escala (
  id       integer PRIMARY KEY,
  cracha   text REFERENCES bomba_equipe(cracha),
  entrada  timestamp,
  saida    timestamp
);

-- Tudo o que as bombas (e a central de infusão) mandam para o servidor.
-- O conteúdo de cada evento vem em JSON, na coluna "dados".
CREATE TABLE bomba_evento (
  id        integer PRIMARY KEY,
  momento   timestamp,
  aparelho  text,          -- 'BMB-01' … 'BMB-16' (as bombas) ou 'CENTRAL' (o computador da farmácia)
  dados     jsonb          -- o evento em si, em JSON
);







-- Segurança: bloqueia acesso pela API pública (o SQL Editor continua funcionando)
ALTER TABLE bomba_equipe ENABLE ROW LEVEL SECURITY;
ALTER TABLE bomba_paciente ENABLE ROW LEVEL SECURITY;
ALTER TABLE bomba_prescricao ENABLE ROW LEVEL SECURITY;
ALTER TABLE bomba_escala ENABLE ROW LEVEL SECURITY;
ALTER TABLE bomba_evento ENABLE ROW LEVEL SECURITY;

-- Conferir a resposta:  SELECT verificar_caso13('resposta');
CREATE FUNCTION verificar_caso13(resposta text) RETURNS text
LANGUAGE sql AS $$
  SELECT CASE md5(lower(trim(resposta)))
    WHEN 'dd698e5a8318413db0f7a87715fdaed0' THEN
      '🏆 CASO ENCERRADO! A central de infusão passou a exigir crachá e senha em toda alteração da biblioteca, e crachá esquecido no posto agora é bloqueado no fim do plantão. O Sr. Aníbal se recuperou. Parabéns, detetive!'
    ELSE
      '❌ Não é essa. Confira se escreveu exatamente como aparece nos dados e revise as pistas.'
  END
$$;

SELECT '✅ Caso 13 instalado! Volte para o guia e comece a Etapa 1.' AS status;
